    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long N = Long.parseLong(br.readLine().trim());

        // Pre-generate suitable numbers up to some limit using Pythagorean triples
        // x = a^2 + a*b where (a,b,c) is a primitive or non-primitive triple
        // Generate triples using Euclid's formula
        int LIMIT = 2000000; // heuristic upper bound
        ArrayList<Long> xs = new ArrayList<>();
        for (long m = 2; m * m <= LIMIT; m++) {
            for (long n = 1; n < m; n++) {
                if (((m - n) & 1) == 0) continue;
                if (gcd(m, n) != 1) continue;
                long a0 = m * m - n * n;
                long b0 = 2 * m * n;
                long c0 = m * m + n * n;
                if (a0 > b0) {
                    long tmp = a0; a0 = b0; b0 = tmp;
                }
                long k = 1;
                while (true) {
                    long a = a0 * k;
                    long b = b0 * k;
                    long c = c0 * k;
                    if (a > LIMIT || b > LIMIT || c > LIMIT) break;
                    long x = a * a + a * b;
                    xs.add(x);
                    k++;
                }
            }
        }

        Collections.sort(xs);
        ArrayList<Long> unique = new ArrayList<>();
        long prev = -1;
        for (long v : xs) {
            if (v != prev) {
                unique.add(v);
                prev = v;
            }
        }

        // If N within precomputed range, output directly
        if (N <= unique.size()) {
            System.out.println(unique.get((int) N - 1));
            return;
        }

        // Otherwise, approximate using arithmetic progression-like growth
        // Use binary search on x, counting how many suitable numbers <= x
        long low = 1, high = (long) 1e18;
        while (low < high) {
            long mid = (low + high) >>> 1;
            long count = countSuitable(mid, unique);
            if (count >= N) high = mid;
            else low = mid + 1;
        }
        System.out.println(low);
    }

    static long countSuitable(long x, ArrayList<Long> pre) {
        int idx = upperBound(pre, x);
        // For larger x beyond precomputed, approximate linearly:
        // density ~ constant; use ratio from precomputed range
        if (idx == 0) return 0;
        long maxPre = pre.get(pre.size() - 1);
        if (x <= maxPre) return idx;
        double density = (double) pre.size() / maxPre;
        long extra = (long) ((x - maxPre) * density);
        return pre.size() + extra;
    }

    static int upperBound(ArrayList<Long> arr, long x) {
        int l = 0, r = arr.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr.get(m) <= x) l = m + 1;
            else r = m;
        }
        return l;
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

