public class Main {
    // Check if x is a perfect square
    static boolean isSquare(long x) {
        long r = (long) Math.sqrt(x);
        return r * r == x || (r + 1) * (r + 1) == x;
    }

    // Count suitable numbers <= X
    static long count(long X) {
        long res = 0;
        long limit = (long) Math.sqrt(X);
        for (long d = 1; d <= limit; d++) {
            long t = X / d;
            if (t < d * d + 2 * d) continue; // minimal b^2 = a^2 + 2a
            long s = t - d * d;
            if (s <= 0) continue;
            long m = (long) Math.sqrt(s);
            if (m < d + 1) continue;
            long cnt = m - d;
            if (cnt > 0) res += cnt;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long N = Long.parseLong(br.readLine().trim());

        long lo = 1, hi = (long) 4e18;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (count(mid) >= N) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}
